WITH species_ids AS (
  SELECT ARRAY_REMOVE(ARRAY[
    (SELECT id FROM public.fish_species WHERE name ILIKE 'Red Snapper' LIMIT 1),
    (SELECT id FROM public.fish_species WHERE name ILIKE 'Mangrove Snapper' LIMIT 1),
    (SELECT id FROM public.fish_species WHERE name ILIKE 'Gag Grouper' LIMIT 1),
    (SELECT id FROM public.fish_species WHERE name ILIKE 'Spanish Mackerel' LIMIT 1),
    (SELECT id FROM public.fish_species WHERE name ILIKE 'King Mackerel' LIMIT 1),
    (SELECT id FROM public.fish_species WHERE name ILIKE 'Sheepshead' LIMIT 1)
  ], NULL)::uuid[] AS ids
)
